import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен", "files": [], "count": 0, "preferred": None}

    roots_param = get_array(params, "roots")
    roots = [str(item or "").strip() for item in roots_param if str(item or "").strip()]
    if not roots:
        roots = ["/session/r7", "/session", "/workspace"]

    files = []
    for root in roots:
        await list_excel_in_dir(vfs, root, files, 0)

    seen = {}
    unique = []
    for item in files:
        path = item.get("path")
        if path in seen:
            continue
        seen[path] = True
        unique.append(item)

    def sort_key(item):
        path = str(item.get("path") or "")
        under_r7 = 0 if path.startswith("/session/r7/") else 1
        return (under_r7, path)

    unique.sort(key=sort_key)

    preferred = None
    r7_files = [f for f in unique if str(f.get("path") or "").startswith("/session/r7/")]
    if len(r7_files) == 1:
        preferred = r7_files[0].get("path")

    return {
        "ok": True,
        "files": unique,
        "count": len(unique),
        "preferred": preferred,
    }

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен", "needsUser": False, "options": []}

    workbook_path = get_string(params, "workbookPath").strip()
    last_result = get_string(params, "lastResultPath").strip()
    user_choice = get_string(params, "userChoice").strip()
    hint = get_string(params, "hint").strip()

    skip_names = {
        "history.md",
        ".tmp",
        "_excel_pivot_out.xlsx",
    }

    def norm_path(p):
        s = str(p or "").strip().replace("\\", "/")
        if s.startswith("~/"):
            s = s[1:]
        if not s.startswith("/") and s.startswith("session/"):
            s = "/" + s
        return s

    def is_excel_path(p):
        lower = p.lower()
        return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

    def short_label(path, sheet):
        name = path.rsplit("/", 1)[-1] if path else "файл"
        if name.lower().startswith("r7-"):
            name = "Исходная книга"
        return name + " · " + str(sheet)

    candidate_paths = []
    for raw in (workbook_path, last_result):
        p = norm_path(raw)
        if p and is_excel_path(p) and p not in candidate_paths:
            candidate_paths.append(p)

    discovered = []
    for root in ("/session/r7", "/session"):
        await list_excel_in_dir(vfs, root, discovered, 0)
    for item in discovered:
        p = norm_path(item.get("path"))
        name = str(item.get("name") or "").strip()
        if not p or not is_excel_path(p):
            continue
        if name.lower() in skip_names:
            continue
        if p not in candidate_paths:
            candidate_paths.append(p)

    options = []
    seen = set()
    idx = 0
    for path in candidate_paths:
        try:
            from openpyxl import load_workbook

            buffer = await read_workbook_bytes(vfs, path)
            wb = load_workbook(io.BytesIO(buffer), read_only=True, data_only=True)
            sheets = list(wb.sheetnames or [])
            try:
                wb.close()
            except Exception:
                pass
        except Exception:
            continue
        if not sheets:
            continue
        for sheet in sheets:
            key = path + "::" + sheet
            if key in seen:
                continue
            seen.add(key)
            idx += 1
            opt_id = "s" + str(idx)
            options.append(
                {
                    "id": opt_id,
                    "label": short_label(path, sheet),
                    "sourcePath": path,
                    "sourceSheet": sheet,
                }
            )

    if not options:
        return {
            "ok": False,
            "error": "Нет доступных .xlsx с листами в session VFS",
            "needsUser": False,
            "options": [],
        }

    def resolve_opt(opt):
        return {
            "ok": True,
            "needsUser": False,
            "sourcePath": opt["sourcePath"],
            "sourceSheet": opt["sourceSheet"],
            "label": opt["label"],
            "options": options,
        }

    def is_open_workbook(path):
        p = norm_path(path).lower()
        return "/session/r7/" in p or p.startswith("/session/r7/")

    def is_result_artifact(path):
        p = norm_path(path).lower()
        name = p.rsplit("/", 1)[-1]
        if is_open_workbook(p):
            return False
        # Agent deliverables: KPI / pivot / filter exports — not the raw open book.
        markers = ("_kpi", "kpi_", "premium_", "_sorted", "_filtered", "_pivot", "сводн")
        if any(m in name for m in markers):
            return True
        return p.startswith("/session/") and not is_open_workbook(p)

    workbook_norm = norm_path(workbook_path)
    last_norm = norm_path(last_result)

    if user_choice:
        choice_l = user_choice.lower().strip()
        for opt in options:
            if opt["id"].lower() == choice_l or opt["label"].lower() == choice_l:
                return resolve_opt(opt)
            if choice_l in opt["label"].lower():
                return resolve_opt(opt)
            if choice_l in opt["sourcePath"].lower() or choice_l in str(opt["sourceSheet"]).lower():
                return resolve_opt(opt)

    if hint:
        hint_l = hint.lower()
        hits = []
        for opt in options:
            blob = (opt["label"] + " " + opt["sourcePath"] + " " + str(opt["sourceSheet"])).lower()
            if hint_l in blob or any(
                tok and tok in blob for tok in hint_l.replace(",", " ").split()
            ):
                hits.append(opt)
        uniq = []
        for h in hits:
            if h not in uniq:
                uniq.append(h)
        if len(uniq) == 1:
            return resolve_opt(uniq[0])

    if len(options) == 1:
        return resolve_opt(options[0])

    # Default: open R7 workbook beats previous KPI/result files.
    # Follow-up questions about raw columns (оклад, город, …) must not land on *_kpi.xlsx.
    if workbook_norm:
        wb_opts = [o for o in options if norm_path(o["sourcePath"]) == workbook_norm]
        if len(wb_opts) == 1:
            return resolve_opt(wb_opts[0])
        if len(wb_opts) > 1:
            return {
                "ok": True,
                "needsUser": True,
                "options": wb_opts,
                "prompt": "На каком листе открытой книги работать?",
            }

    primary = [o for o in options if not is_result_artifact(o["sourcePath"])]
    if len(primary) == 1:
        return resolve_opt(primary[0])
    if len(primary) > 1:
        return {
            "ok": True,
            "needsUser": True,
            "options": primary,
            "prompt": "С какой таблицей работать дальше?",
        }

    # Only result artifacts left — ask (or auto last_result if single).
    if last_norm:
        last_opts = [o for o in options if norm_path(o["sourcePath"]) == last_norm]
        if len(last_opts) == 1:
            return resolve_opt(last_opts[0])

    return {
        "ok": True,
        "needsUser": True,
        "options": options,
        "prompt": "С какой таблицей работать дальше?",
    }

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    file_path = get_string(params, "path").strip()
    if not file_path:
        return {"ok": False, "error": "path обязателен"}

    sheet = get_string(params, "sheet").strip()
    sample_rows = 5
    raw_sample = params.get("sampleRows")
    if isinstance(raw_sample, (int, float)) and math.isfinite(float(raw_sample)):
        sample_rows = max(1, min(20, int(round(float(raw_sample)))))

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, file_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, sheet)
        columns = classify_columns(parsed["headers"], parsed["rows"], 50)
        suggested = suggest_pivot(columns)
        sample = parsed["rows"][:sample_rows]
        return {
            "ok": True,
            "path": file_path,
            "sheets": list(wb.sheetnames),
            "sheet": parsed["sheetName"],
            "headers": parsed["headers"],
            "rowCount": len(parsed["rows"]),
            "sample": sample,
            "columns": columns,
            "suggestedPivot": suggested,
        }
    except Exception as err:
        return {"ok": False, "error": str(err), "path": file_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    target_path = normalize_result_path(
        get_string(params, "targetPath").strip(),
        source_path,
        "pivot",
    )
    source_sheet = get_string(params, "sourceSheet").strip()
    target_sheet = get_string(params, "targetSheet").strip() or "Сводная"
    row_fields = [str(item or "").strip() for item in get_array(params, "rowFields") if str(item or "").strip()]
    column_fields = [str(item or "").strip() for item in get_array(params, "columnFields") if str(item or "").strip()]
    value_field = get_string(params, "valueField").strip()
    aggregation = get_string(params, "aggregation").strip().lower() or "sum"
    if aggregation not in ("sum", "count", "avg", "min", "max"):
        aggregation = "sum"

    preview_rows = 10
    raw_preview = params.get("previewRows")
    if isinstance(raw_preview, (int, float)) and math.isfinite(float(raw_preview)):
        preview_rows = max(1, min(30, int(round(float(raw_preview)))))

    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    if not row_fields:
        return {"ok": False, "error": "rowFields обязателен (минимум одно поле)"}
    if not value_field:
        return {"ok": False, "error": "valueField обязателен"}

    try:
        from openpyxl import Workbook, load_workbook
        from openpyxl.utils import get_column_letter

        source_buffer = await read_workbook_bytes(vfs, source_path)
        source_wb = load_workbook(io.BytesIO(source_buffer), data_only=True)
        parsed = sheet_to_records(source_wb, source_sheet)

        header_set = {h: True for h in parsed["headers"]}
        missing = []
        for field in row_fields:
            if field not in header_set:
                missing.append(field)
        for field in column_fields:
            if field not in header_set:
                missing.append(field)
        if value_field not in header_set:
            missing.append(value_field)
        if missing:
            return {
                "ok": False,
                "error": "Неизвестные колонки: " + ", ".join(missing) + ". Доступны: " + ", ".join(parsed["headers"]),
            }

        pivot = build_pivot_aoa(
            parsed["rows"],
            {
                "rowFields": row_fields,
                "columnFields": column_fields,
                "valueField": value_field,
                "aggregation": aggregation,
            },
        )

        created_new = False
        if target_path == source_path:
            # Reload without data_only to preserve formulas/styles if any; for smoke we rewrite from buffer.
            target_wb = load_workbook(io.BytesIO(source_buffer), data_only=False)
        else:
            exists = False
            if callable(getattr(vfs, "exists", None)):
                try:
                    exists = bool(await vfs.exists(target_path))
                except Exception:
                    exists = False
            if exists:
                target_buffer = await read_workbook_bytes(vfs, target_path)
                target_wb = load_workbook(io.BytesIO(target_buffer), data_only=False)
            else:
                target_wb = Workbook()
                created_new = True
                default = target_wb.active
                target_wb.remove(default)

        if target_sheet in target_wb.sheetnames:
            del target_wb[target_sheet]
        ws = target_wb.create_sheet(title=target_sheet)

        for r_idx, row in enumerate(pivot["aoa"], start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)

        for col in range(1, pivot["columnCount"] + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

        out = io.BytesIO()
        target_wb.save(out)
        payload = out.getvalue()
        write_mode = await write_workbook_bytes(vfs, target_path, payload)

        stored = None
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(target_path)
                if isinstance(meta, dict):
                    stored = meta.get("size_bytes") or meta.get("size")
            except Exception:
                stored = None

        return analytics_done(
            target_path,
            "Сводная «"
            + target_sheet
            + "»: "
            + str(pivot["rowCount"])
            + " строк, "
            + aggregation
            + " по «"
            + value_field
            + "».",
            sourcePath=source_path,
            targetSheet=target_sheet,
            writeMode=write_mode + ("+created" if created_new else "+updated"),
            expectedBytes=len(payload),
            storedBytes=stored,
            pivotRows=pivot["rowCount"],
            pivotColumns=pivot["columnCount"],
            aggregation=pivot["aggregation"],
            valueField=pivot["valueField"],
            rowFields=row_fields,
            columnFields=column_fields[:1],
            preview=pivot["aoa"][: preview_rows + 1],
        )
    except Exception as err:
        return {
            "ok": False,
            "error": str(err),
            "sourcePath": source_path,
            "targetPath": target_path,
            "targetSheet": target_sheet,
        }

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "profile")
    target_sheet = get_string(params, "targetSheet").strip() or "Профиль"
    key_fields = [str(x or "").strip() for x in get_array(params, "keyFields") if str(x or "").strip()]
    top_n = 5
    raw_top = params.get("topN")
    if isinstance(raw_top, (int, float)) and math.isfinite(float(raw_top)):
        top_n = max(1, min(20, int(round(float(raw_top)))))

    try:
        from openpyxl import load_workbook
        from collections import Counter

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        headers = parsed["headers"]
        rows = parsed["rows"]
        n = len(rows)

        aoa = [["Колонка", "nonEmpty", "nullPct", "unique", "kind", "min", "max", "topValues"]]
        columns_out = []
        for header in headers:
            values = [row.get(header) for row in rows]
            non_empty = [v for v in values if v is not None and v != ""]
            null_pct = round(100.0 * (n - len(non_empty)) / n, 1) if n else 0.0
            uniq = {}
            for v in non_empty:
                uniq[cell_key(v)] = v
            nums = [to_number(v) for v in non_empty]
            nums = [x for x in nums if math.isfinite(x)]
            kind = "numeric" if nums and len(nums) >= max(1, int(0.8 * len(non_empty))) else "text"
            mn = round_smart(min(nums)) if nums else None
            mx = round_smart(max(nums)) if nums else None
            counts = Counter(cell_key(v) for v in non_empty)
            top = []
            for key, cnt in counts.most_common(top_n):
                sample = next((v for v in non_empty if cell_key(v) == key), key)
                top.append({"value": sample, "count": cnt})
            top_str = "; ".join(str(t["value"]) + "(" + str(t["count"]) + ")" for t in top)
            aoa.append([header, len(non_empty), null_pct, len(uniq), kind, mn, mx, top_str])
            columns_out.append({
                "name": header,
                "nonEmpty": len(non_empty),
                "nullPct": null_pct,
                "unique": len(uniq),
                "kind": kind,
                "min": mn,
                "max": mx,
                "topValues": top,
            })

        dup_count = 0
        if key_fields:
            seen = {}
            for row in rows:
                key = "\u0001".join(cell_key(row.get(f)) for f in key_fields)
                if key in seen:
                    dup_count += 1
                else:
                    seen[key] = True
            aoa.append([])
            aoa.append(["keyFields", ", ".join(key_fields), "duplicateRows", dup_count])

        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Профиль листа «" + str(parsed["sheetName"]) + "»: " + str(n) + " строк.",
            sourcePath=source_path,
            targetSheet=target_sheet,
            sheet=parsed["sheetName"],
            rowCount=n,
            columns=columns_out,
            duplicateRows=dup_count if key_fields else None,
            preview=aoa[: min(12, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "deduped")
    target_sheet = get_string(params, "targetSheet").strip() or "Данные"
    key_fields = [str(x or "").strip() for x in get_array(params, "keyFields") if str(x or "").strip()]
    keep = get_string(params, "keep").strip().lower() or "first"
    if keep not in ("first", "last"):
        keep = "first"
    normalize = params.get("normalizeHeaders")
    do_norm = True if normalize is None else bool(normalize)

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        headers = list(parsed["headers"])
        rows = list(parsed["rows"])
        before = len(rows)

        if do_norm:
            new_headers = []
            rename = {}
            used = {}
            for h in headers:
                base = re.sub(r"\s+", " ", str(h or "").strip())
                if not base:
                    base = "col"
                key = base
                n = 2
                while key in used:
                    key = base + "_" + str(n)
                    n += 1
                used[key] = True
                rename[h] = key
                new_headers.append(key)
            rows = [{rename[h]: row.get(h) for h in headers} for row in rows]
            headers = new_headers

        removed = 0
        if key_fields:
            missing = [f for f in key_fields if f not in headers]
            if missing:
                return {"ok": False, "error": "Неизвестные keyFields: " + ", ".join(missing)}
            if keep == "first":
                seen = {}
                out_rows = []
                for row in rows:
                    key = "\u0001".join(cell_key(row.get(f)) for f in key_fields)
                    if key in seen:
                        removed += 1
                        continue
                    seen[key] = True
                    out_rows.append(row)
                rows = out_rows
            else:
                seen = {}
                out_rows = []
                for row in reversed(rows):
                    key = "\u0001".join(cell_key(row.get(f)) for f in key_fields)
                    if key in seen:
                        removed += 1
                        continue
                    seen[key] = True
                    out_rows.append(row)
                rows = list(reversed(out_rows))

        aoa = records_to_aoa(headers, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Дубликаты удалены: было "
            + str(before)
            + ", стало "
            + str(len(rows))
            + ", снято "
            + str(removed)
            + ".",
            sourcePath=source_path,
            targetSheet=target_sheet,
            headers=headers,
            rowCountBefore=before,
            rowCountAfter=len(rows),
            removedDuplicates=removed,
            keyFields=key_fields,
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "filter")
    target_sheet = get_string(params, "targetSheet").strip() or "Фильтр"
    filters = get_array(params, "filters")
    match_any = bool(params.get("matchAny") is True or params.get("match_any") is True)
    # Optional projection — only when explicitly provided (keep all columns by default).
    columns = [str(x or "").strip() for x in get_array(params, "columns") if str(x or "").strip()]

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        headers = list(parsed["headers"])
        if columns:
            missing = [c for c in columns if c not in headers]
            if missing:
                return {
                    "ok": False,
                    "error": "Нет колонок: " + ", ".join(missing) + ". Есть: " + ", ".join(headers),
                    "sourcePath": source_path,
                }
            headers = columns
        before = len(parsed["rows"])
        rows = [
            row
            for row in parsed["rows"]
            if row_matches_filters(row, filters, match_any)
        ]
        if columns:
            rows = [{c: row.get(c) for c in headers} for row in rows]
        aoa = records_to_aoa(headers, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        summary = (
            "Фильтр применён: строк "
            + str(before)
            + " → "
            + str(len(rows))
            + "."
        )
        return analytics_done(
            target_path,
            summary,
            sourcePath=source_path,
            targetSheet=target_sheet,
            filters=filters,
            matchAny=match_any,
            columns=headers,
            rowCountBefore=before,
            rowCountAfter=len(rows),
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "columns")
    target_sheet = get_string(params, "targetSheet").strip() or "Данные"
    columns = [str(x or "").strip() for x in get_array(params, "columns") if str(x or "").strip()]
    if not columns:
        return {"ok": False, "error": "columns обязателен (непустой список)"}

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        missing = [c for c in columns if c not in parsed["headers"]]
        if missing:
            return {
                "ok": False,
                "error": "Нет колонок: " + ", ".join(missing) + ". Есть: " + ", ".join(parsed["headers"]),
            }
        rows = [{c: row.get(c) for c in columns} for row in parsed["rows"]]
        aoa = records_to_aoa(columns, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Выбраны колонки: " + ", ".join(columns) + ".",
            sourcePath=source_path,
            targetSheet=target_sheet,
            columns=columns,
            rowCount=len(rows),
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(
        get_string(params, "targetPath").strip(),
        source_path,
        "sort",
    )
    target_sheet = get_string(params, "targetSheet").strip() or "Данные"
    sort_by = [str(x or "").strip() for x in get_array(params, "sortBy") if str(x or "").strip()]
    if not sort_by:
        one = get_string(params, "sortField").strip()
        if one:
            sort_by = [one]
    ascending = params.get("ascending")
    asc = True if ascending is None else bool(ascending)

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        headers = parsed["headers"]
        if not sort_by:
            return {"ok": False, "error": "sortBy или sortField обязателен"}
        missing = [f for f in sort_by if f not in headers]
        if missing:
            return {"ok": False, "error": "Нет полей сортировки: " + ", ".join(missing)}

        def sort_key(row):
            parts = []
            for field in sort_by:
                val = row.get(field)
                num = to_number(val)
                if math.isfinite(num):
                    parts.append((0, num, ""))
                else:
                    # Natural order: Сотр_1 < Сотр_2 < Сотр_10 (not lexicographic).
                    parts.append((1, 0.0, natural_sort_key(val)))
            return parts

        rows = sorted(parsed["rows"], key=sort_key, reverse=not asc)
        aoa = records_to_aoa(headers, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        summary = "Таблица отсортирована по: " + ", ".join(sort_by) + "."
        return analytics_done(
            target_path,
            summary,
            sourcePath=source_path,
            targetSheet=target_sheet,
            sortBy=sort_by,
            ascending=asc,
            rowCount=len(rows),
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "calc")
    target_sheet = get_string(params, "targetSheet").strip() or "Данные"
    new_column = get_string(params, "newColumn").strip()
    expression = get_string(params, "expression").strip()
    if not new_column or not expression:
        return {"ok": False, "error": "newColumn и expression обязательны"}

    # Safe ops: "Кол * Цена", "A + B", "A - B", "A / B" using column names as tokens
    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        headers = list(parsed["headers"])
        if new_column in headers:
            return {"ok": False, "error": "Колонка уже есть: " + new_column}

        # Map longer names first to avoid partial replaces
        names = sorted(headers, key=lambda x: len(x), reverse=True)

        def eval_expr(row):
            expr = expression
            for name in names:
                if name and name in expr:
                    expr = expr.replace(name, str(to_number(row.get(name))))
            expr = expr.replace(",", ".")
            if not re.fullmatch(r"[0-9eE+\-*/().\s]+", expr or ""):
                raise ValueError("Небезопасное или непонятное expression: " + expression)
            return round_smart(eval(expr, {"__builtins__": {}}, {}))

        rows = []
        for row in parsed["rows"]:
            item = dict(row)
            try:
                item[new_column] = eval_expr(row)
            except Exception:
                item[new_column] = None
            rows.append(item)
        out_headers = headers + [new_column]
        aoa = records_to_aoa(out_headers, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Добавлена колонка «" + new_column + "» = " + expression + ".",
            sourcePath=source_path,
            targetSheet=target_sheet,
            newColumn=new_column,
            expression=expression,
            rowCount=len(rows),
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "periods")
    target_sheet = get_string(params, "targetSheet").strip() or "Данные"
    date_field = get_string(params, "dateField").strip()
    bucket = get_string(params, "bucket").strip().lower() or "month"
    new_column = get_string(params, "newColumn").strip() or ("Период_" + bucket)
    if bucket not in ("day", "week", "month", "year"):
        bucket = "month"
    if not date_field:
        return {"ok": False, "error": "dateField обязателен"}

    try:
        from openpyxl import load_workbook
        from datetime import datetime, date, timedelta

        def parse_date(value):
            if isinstance(value, datetime):
                return value.date()
            if isinstance(value, date):
                return value
            if value is None or value == "":
                return None
            text = str(value).strip()
            for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
                try:
                    return datetime.strptime(text[:19], fmt).date()
                except Exception:
                    continue
            try:
                return datetime.fromisoformat(text.replace("Z", "")).date()
            except Exception:
                return None

        def bucket_label(d):
            if d is None:
                return ""
            if bucket == "day":
                return d.isoformat()
            if bucket == "year":
                return str(d.year)
            if bucket == "week":
                iso = d.isocalendar()
                return str(iso[0]) + "-W" + str(iso[1]).zfill(2)
            return str(d.year) + "-" + str(d.month).zfill(2)

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        if date_field not in parsed["headers"]:
            return {"ok": False, "error": "Нет dateField: " + date_field}
        headers = list(parsed["headers"])
        if new_column not in headers:
            headers = headers + [new_column]
        rows = []
        for row in parsed["rows"]:
            item = dict(row)
            item[new_column] = bucket_label(parse_date(row.get(date_field)))
            rows.append(item)
        aoa = records_to_aoa(headers, rows)
        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [{"name": target_sheet, "aoa": aoa}],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Периоды по «" + date_field + "» (" + bucket + ").",
            sourcePath=source_path,
            targetSheet=target_sheet,
            dateField=date_field,
            bucket=bucket,
            newColumn=new_column,
            rowCount=len(rows),
            preview=aoa[: min(11, len(aoa))],
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    source_sheet = get_string(params, "sourceSheet").strip()
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "top")
    category_field = get_string(params, "categoryField").strip()
    value_field = get_string(params, "valueField").strip()
    aggregation = get_string(params, "aggregation").strip().lower() or "sum"
    if aggregation not in ("sum", "count", "avg", "min", "max"):
        aggregation = "sum"
    top_n = 10
    raw_n = params.get("topN")
    if isinstance(raw_n, (int, float)) and math.isfinite(float(raw_n)):
        top_n = max(1, min(50, int(round(float(raw_n)))))
    include_other = bool(params.get("includeOther")) if params.get("includeOther") is not None else True
    if not category_field or not value_field:
        return {"ok": False, "error": "categoryField и valueField обязательны"}

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        parsed = sheet_to_records(wb, source_sheet)
        for field in (category_field, value_field):
            if field not in parsed["headers"]:
                return {"ok": False, "error": "Нет колонки: " + field}

        groups = {}
        for row in parsed["rows"]:
            key = cell_key(row.get(category_field))
            if key not in groups:
                groups[key] = {"label": row.get(category_field), "values": []}
            if aggregation == "count":
                groups[key]["values"].append(1.0)
            else:
                n = to_number(row.get(value_field))
                if math.isfinite(n):
                    groups[key]["values"].append(n)

        ranked = []
        for g in groups.values():
            agg = aggregate(g["values"], aggregation)
            ranked.append({"category": g["label"], "value": None if agg is None else round_smart(agg)})
        ranked.sort(key=lambda x: (x["value"] is None, -(x["value"] or 0)))

        top = ranked[:top_n]
        other_vals = [x["value"] for x in ranked[top_n:] if x["value"] is not None]
        kpi_total = aggregate([x["value"] for x in ranked if x["value"] is not None], "sum")
        top_aoa = [[category_field, value_field + " (" + aggregation + ")"]]
        for item in top:
            top_aoa.append([item["category"], item["value"]])
        if include_other and other_vals:
            top_aoa.append(["Прочее", round_smart(aggregate(other_vals, "sum"))])

        kpi_aoa = [
            ["Метрика", "Значение"],
            ["Всего категорий", len(ranked)],
            ["Топ N", top_n],
            ["Сумма меры", None if kpi_total is None else round_smart(kpi_total)],
        ]
        if top:
            kpi_aoa.append(["Лидер", top[0]["category"]])
            kpi_aoa.append(["Значение лидера", top[0]["value"]])

        write_info = await write_aoa_workbook(
            vfs,
            target_path,
            [
                {"name": "Топ", "aoa": top_aoa},
                {"name": "KPI", "aoa": kpi_aoa},
            ],
            source_path if target_path == source_path else None,
        )
        return analytics_done(
            target_path,
            "Топ-"
            + str(top_n)
            + " по «"
            + category_field
            + "» / «"
            + value_field
            + "» ("
            + aggregation
            + ").",
            sourcePath=source_path,
            categoryField=category_field,
            valueField=value_field,
            aggregation=aggregation,
            topN=top_n,
            preview=top_aoa[: min(12, len(top_aoa))],
            kpi=kpi_aoa,
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    params = params if isinstance(params, dict) else {}
    vfs = get_vfs(state)
    if not vfs:
        return {"ok": False, "error": "VFS недоступен"}

    source_path = get_string(params, "sourcePath").strip()
    if not source_path:
        return {"ok": False, "error": "sourcePath обязателен"}
    sheet_a = get_string(params, "sheetA").strip()
    sheet_b = get_string(params, "sheetB").strip()
    if not sheet_a or not sheet_b:
        return {"ok": False, "error": "sheetA и sheetB обязательны"}
    key_fields = [str(x or "").strip() for x in get_array(params, "keyFields") if str(x or "").strip()]
    mode = get_string(params, "mode").strip().lower() or "diff"
    if mode not in ("diff", "join", "reconcile"):
        mode = "diff"
    value_field = get_string(params, "valueField").strip()
    tolerance = 0.01
    raw_tol = params.get("tolerance")
    if isinstance(raw_tol, (int, float)) and math.isfinite(float(raw_tol)):
        tolerance = abs(float(raw_tol))
    target_path = normalize_result_path(get_string(params, "targetPath").strip(), source_path, "compare")

    try:
        from openpyxl import load_workbook

        buffer = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buffer), data_only=True)
        if sheet_a not in wb.sheetnames or sheet_b not in wb.sheetnames:
            return {
                "ok": False,
                "error": "Листы не найдены. Есть: " + ", ".join(wb.sheetnames),
                "sheets": list(wb.sheetnames),
            }
        a = sheet_to_records(wb, sheet_a)
        b = sheet_to_records(wb, sheet_b)
        if not key_fields:
            common = [h for h in a["headers"] if h in b["headers"]]
            if not common:
                return {"ok": False, "error": "Нет общих колонок для ключа; укажите keyFields"}
            key_fields = [common[0]]

        for field in key_fields:
            if field not in a["headers"] or field not in b["headers"]:
                return {"ok": False, "error": "keyField отсутствует на одном из листов: " + field}

        def index_rows(parsed):
            out = {}
            for row in parsed["rows"]:
                key = "\u0001".join(cell_key(row.get(f)) for f in key_fields)
                if key not in out:
                    out[key] = row
            return out

        map_a = index_rows(a)
        map_b = index_rows(b)
        keys_a = set(map_a.keys())
        keys_b = set(map_b.keys())
        only_a = sorted(keys_a - keys_b)
        only_b = sorted(keys_b - keys_a)
        both = sorted(keys_a & keys_b)

        def row_aoa(headers, rows_list):
            return records_to_aoa(headers, rows_list)

        sheets = []
        stats = {
            "onlyA": len(only_a),
            "onlyB": len(only_b),
            "matched": len(both),
            "changed": 0,
            "reconcileDiffs": 0,
        }

        if mode == "join":
            headers = list(key_fields)
            for h in a["headers"]:
                if h not in headers:
                    headers.append(h + "_A")
            for h in b["headers"]:
                if h not in key_fields:
                    headers.append(h + "_B")
            joined = []
            for key in sorted(keys_a | keys_b):
                ra = map_a.get(key)
                rb = map_b.get(key)
                item = {}
                for f in key_fields:
                    item[f] = (ra or rb).get(f) if (ra or rb) else ""
                if ra:
                    for h in a["headers"]:
                        if h not in key_fields:
                            item[h + "_A"] = ra.get(h)
                if rb:
                    for h in b["headers"]:
                        if h not in key_fields:
                            item[h + "_B"] = rb.get(h)
                joined.append(item)
            sheets.append({"name": "Join", "aoa": row_aoa(headers, joined)})
        else:
            sheets.append({
                "name": "Только_" + sheet_a[:20],
                "aoa": row_aoa(a["headers"], [map_a[k] for k in only_a]),
            })
            sheets.append({
                "name": "Только_" + sheet_b[:20],
                "aoa": row_aoa(b["headers"], [map_b[k] for k in only_b]),
            })
            same_headers = [h for h in a["headers"] if h in b["headers"]]
            matched_rows = []
            changed_rows = []
            for key in both:
                ra = map_a[key]
                rb = map_b[key]
                diff_cols = []
                for h in same_headers:
                    if h in key_fields:
                        continue
                    if cell_key(ra.get(h)) != cell_key(rb.get(h)):
                        diff_cols.append(h)
                if diff_cols:
                    stats["changed"] += 1
                    item = {f: ra.get(f) for f in key_fields}
                    item["changedFields"] = ", ".join(diff_cols)
                    for h in diff_cols:
                        item[h + "_A"] = ra.get(h)
                        item[h + "_B"] = rb.get(h)
                    changed_rows.append(item)
                else:
                    matched_rows.append(ra)
            sheets.append({"name": "Совпадают", "aoa": row_aoa(a["headers"], matched_rows)})
            if changed_rows:
                ch_headers = key_fields + ["changedFields"]
                for row in changed_rows:
                    for k in row.keys():
                        if k not in ch_headers:
                            ch_headers.append(k)
                sheets.append({"name": "Расхождения", "aoa": row_aoa(ch_headers, changed_rows)})

            if mode == "reconcile":
                if not value_field:
                    return {"ok": False, "error": "для mode=reconcile укажите valueField"}
                if value_field not in a["headers"] or value_field not in b["headers"]:
                    return {"ok": False, "error": "valueField нет на обоих листах"}
                rec_rows = []
                for key in both:
                    ra = map_a[key]
                    rb = map_b[key]
                    va = to_number(ra.get(value_field))
                    vb = to_number(rb.get(value_field))
                    if not math.isfinite(va):
                        va = 0.0
                    if not math.isfinite(vb):
                        vb = 0.0
                    delta = va - vb
                    if abs(delta) > tolerance:
                        stats["reconcileDiffs"] += 1
                        item = {f: ra.get(f) for f in key_fields}
                        item[value_field + "_A"] = round_smart(va)
                        item[value_field + "_B"] = round_smart(vb)
                        item["delta"] = round_smart(delta)
                        rec_rows.append(item)
                rec_headers = key_fields + [value_field + "_A", value_field + "_B", "delta"]
                sheets.append({"name": "Сверка_сумм", "aoa": row_aoa(rec_headers, rec_rows)})

        write_info = await write_aoa_workbook(vfs, target_path, sheets, None)
        preview = sheets[0]["aoa"][: min(8, len(sheets[0]["aoa"]))] if sheets else []
        return analytics_done(
            target_path,
            "Сверка листов «" + sheet_a + "» / «" + sheet_b + "» (" + mode + ").",
            sourcePath=source_path,
            sheetA=sheet_a,
            sheetB=sheet_b,
            keyFields=key_fields,
            mode=mode,
            stats=stats,
            resultSheets=[s["name"] for s in sheets],
            preview=preview,
            **write_info,
        )
    except Exception as err:
        return {"ok": False, "error": str(err), "sourcePath": source_path}

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    """
    Disabled for agent auto-apply. Open-sheet overwrite is the plugin
    «Заменить» button (or local phrase intent). Returning ok:false prevents
    the plugin from applying sheet_replace_from_xlsx.
    """
    params = params if isinstance(params, dict) else {}
    source_path = get_string(params, "sourcePath").strip()
    return {
        "ok": False,
        "error": (
            "Перезапись открытого листа делает плагин (кнопка «Заменить» / «Лист» / «Вставить»). "
            "После sort/filter/pivot ответь строкой Файл: <targetPath> и остановись. "
            "Не вызывай sheet_replace."
        ),
        "hint": "plugin_replace_button",
        "sourcePath": source_path or None,
    }

import base64
import io
import math
import re
from collections import defaultdict

def as_dict(value):
    return value if isinstance(value, dict) else None

def get_string(source, key):
    obj = as_dict(source)
    if not obj:
        return ""
    value = obj.get(key)
    return value if isinstance(value, str) else ""

def get_array(source, key):
    obj = as_dict(source)
    if not obj:
        return []
    value = obj.get(key)
    return value if isinstance(value, list) else []

def get_vfs(state):
    caps = as_dict(state.get("capabilities") if isinstance(state, dict) else getattr(state, "capabilities", None))
    if caps is None and hasattr(state, "capabilities"):
        caps = as_dict(state.capabilities)
    if not caps:
        return None
    vfs = caps.get("vfs") if isinstance(caps, dict) else getattr(caps, "vfs", None)
    if vfs is None:
        return None
    if not callable(getattr(vfs, "readFile", None)) or not callable(getattr(vfs, "writeFile", None)):
        return None
    return vfs

def looks_like_zip(data):
    return isinstance(data, (bytes, bytearray)) and len(data) >= 2 and data[0] == 0x50 and data[1] == 0x4B

def decode_workbook_bytes(raw):
    if isinstance(raw, memoryview):
        raw = raw.tobytes()
    if isinstance(raw, bytearray):
        raw = bytes(raw)
    if isinstance(raw, bytes):
        return raw
    if isinstance(raw, dict) and raw.get("type") == "Buffer" and isinstance(raw.get("data"), list):
        return bytes(raw["data"])
    if not isinstance(raw, str):
        raise ValueError("VFS вернул неподдерживаемый тип содержимого workbook")
    if len(raw) >= 2 and ord(raw[0]) == 0x50 and ord(raw[1]) == 0x4B:
        return raw.encode("latin-1")
    compact = re.sub(r"\s+", "", raw)
    if re.fullmatch(r"[A-Za-z0-9+/=]+", compact or "") and len(compact) >= 8:
        try:
            b64 = base64.b64decode(compact)
            if looks_like_zip(b64):
                return b64
        except Exception:
            pass
    binary = raw.encode("latin-1")
    if looks_like_zip(binary):
        return binary
    raise ValueError("Не удалось декодировать .xlsx как ZIP/PK (binary/base64)")

async def read_workbook_bytes(vfs, file_path):
    raw = None
    last_error = None
    try:
        raw = await vfs.readFile(file_path, {"source": "original"})
    except Exception as err:
        last_error = err
    if raw is None:
        try:
            raw = await vfs.readFile(file_path)
        except Exception as err:
            last_error = err
    if raw is None:
        message = str(last_error) if last_error else "пусто"
        raise ValueError("Не удалось прочитать файл: " + file_path + " (" + message + ")")
    return decode_workbook_bytes(raw)

async def write_workbook_bytes(vfs, file_path, data):
    import os
    import tempfile

    payload = bytes(data)
    if not looks_like_zip(payload):
        raise ValueError("Внутренняя ошибка: payload не похож на .xlsx (нет PK)")

    expected = len(payload)
    modes_tried = []

    async def stored_size(path):
        if callable(getattr(vfs, "getFileMetadata", None)):
            try:
                meta = await vfs.getFileMetadata(path)
                if isinstance(meta, dict):
                    for key in ("size_bytes", "size", "length", "byteLength"):
                        if isinstance(meta.get(key), (int, float)):
                            return int(meta.get(key))
                    nested = meta.get("file") or meta.get("data") or {}
                    if isinstance(nested, dict):
                        for key in ("size_bytes", "size", "length"):
                            if isinstance(nested.get(key), (int, float)):
                                return int(nested.get(key))
            except Exception:
                pass
        # FS probe
        try:
            return os.path.getsize(path)
        except Exception:
            return None

    async def verify_binary_storage(path, mode_name):
        """
        VFS readFile(string) маскирует UTF-8 порчу: latin-1 roundtrip
        'чинит' байты в памяти, но download/R7 видят битый файл.
        Поэтому сверяем размер на хранилище с len(payload).
        """
        size = await stored_size(path)
        if size is None:
            # Fallback: FS raw read
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw == payload:
                    return True, size
                modes_tried.append(mode_name + ":fs-mismatch:" + str(len(raw)))
                return False, len(raw)
            except Exception as err:
                modes_tried.append(mode_name + ":no-size:" + str(err))
                return False, None
        if size != expected:
            modes_tried.append(mode_name + ":size " + str(size) + "!=" + str(expected))
            return False, size
        # Extra: openpyxl on FS bytes if readable
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            from openpyxl import load_workbook
            load_workbook(io.BytesIO(raw))
        except Exception:
            pass
        return True, size

    def fs_candidates(path):
        out = [path]
        if path.startswith("/"):
            out.append("~" + path)
            out.append(os.path.expanduser("~" + path))
        if path.startswith("/session/"):
            rel = path[len("/session/") :]
            out.extend(
                [
                    os.path.join("/session", rel),
                    os.path.join(os.path.expanduser("~/session"), rel),
                    os.path.join("/var/ladcraft/session", rel),
                    os.path.join("/tmp/session", rel),
                ]
            )
        # unique preserve order
        seen = {}
        uniq = []
        for item in out:
            if item and item not in seen:
                seen[item] = True
                uniq.append(item)
        return uniq

    # 1) Прямая бинарная запись в FS (единственный надёжный канал для R7)
    for cand in fs_candidates(file_path):
        try:
            parent = os.path.dirname(cand)
            if parent and parent not in (".", "/"):
                os.makedirs(parent, exist_ok=True)
            with open(cand, "wb") as fh:
                fh.write(payload)
            with open(cand, "rb") as fh:
                raw = fh.read()
            if raw != payload:
                modes_tried.append("fs:" + cand + ":mismatch")
                continue
            from openpyxl import load_workbook

            load_workbook(io.BytesIO(raw))
            # Если писали не в канонический VFS-путь — скопируем через vfs.cp/write
            if cand != file_path and callable(getattr(vfs, "cp", None)):
                try:
                    await vfs.cp(cand, file_path)
                except Exception:
                    pass
            ok, _size = await verify_binary_storage(file_path, "fs")
            if ok or raw == payload:
                # Если канонический path недоступен по meta, но FS запись по cand==file_path ок
                if cand == file_path or ok:
                    return "fs"
                # Запись во временный FS + попытка прокинуть bytes через vfs
                modes_tried.append("fs-alt-ok:" + cand)
                # keep alt path content; try vfs write strategies below using payload
            else:
                modes_tried.append("fs:" + cand + ":meta-fail")
        except Exception as err:
            modes_tried.append("fs:" + cand + ":" + str(err))

    # 1b) tempfile + cp в target
    try:
        tmp_dir = "/session/.tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
            tmp_path = os.path.join(tmp_dir, "_excel_pivot_out.xlsx")
        except Exception:
            fd, tmp_path = tempfile.mkstemp(suffix=".xlsx")
            os.close(fd)
        with open(tmp_path, "wb") as fh:
            fh.write(payload)
        if callable(getattr(vfs, "cp", None)):
            await vfs.cp(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+cp")
            if ok:
                return "tmp+cp"
        if callable(getattr(vfs, "mv", None)):
            await vfs.mv(tmp_path, file_path)
            ok, _size = await verify_binary_storage(file_path, "tmp+mv")
            if ok:
                return "tmp+mv"
        modes_tried.append("tmp+cp/mv:meta-fail")
    except Exception as err:
        modes_tried.append("tmp:" + str(err))

    # 2) bytes / bytearray / Buffer-shape через writeFile
    byte_variants = [
        ("bytes", payload),
        ("bytearray", bytearray(payload)),
        ("buffer-dict", {"type": "Buffer", "data": list(payload)}),
        ("int-list", list(payload)),
    ]
    for name, value in byte_variants:
        try:
            await vfs.writeFile(file_path, value)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 3) base64 + encoding option (если runtime умеет декодировать при записи)
    b64 = base64.b64encode(payload).decode("ascii")
    option_variants = [
        ("b64-opt", b64, {"encoding": "base64"}),
        ("b64-opt2", b64, {"contentEncoding": "base64"}),
        ("b64-opt3", b64, {"encoding": "base64", "binary": True}),
        ("b64-opt4", payload.decode("latin-1"), {"encoding": "binary"}),
        ("b64-opt5", payload.decode("latin-1"), {"binary": True}),
    ]
    for name, value, opts in option_variants:
        try:
            await vfs.writeFile(file_path, value, opts)
            ok, _size = await verify_binary_storage(file_path, name)
            if ok:
                return name
        except TypeError:
            modes_tried.append(name + ":no-options")
        except Exception as err:
            modes_tried.append(name + ":" + str(err))

    # 4) Явно ЗАПРЕЩАЕМ latin-1 string без проверки размера:
    #    она даёт «ok» при readFile, но R7/Excel получают UTF-8-битый ZIP.
    try:
        await vfs.writeFile(file_path, payload.decode("latin-1"))
        ok, size = await verify_binary_storage(file_path, "binary-string")
        if ok:
            return "binary-string"
        modes_tried.append(
            "binary-string:rejected-corrupt-for-R7(size=" + str(size) + ")"
        )
    except Exception as err:
        modes_tried.append("binary-string:" + str(err))

    raise ValueError(
        "Не удалось записать бинарный .xlsx для R7/Excel (нужен ZIP без UTF-8 порчи). "
        "expected_size="
        + str(expected)
        + ". Пробы: "
        + " | ".join(modes_tried)
    )

def normalize_header(value):
    if value is None:
        return ""
    return str(value).strip()

def cell_key(value):
    if value is None or value == "":
        return "(пусто)"
    return str(value).strip()

def natural_sort_key(value):
    """Сотр_2 before Сотр_10; digits as ints, text lowercased."""
    s = cell_key(value).lower()
    parts = []
    for chunk in re.findall(r"\d+|\D+", s):
        if chunk.isdigit():
            parts.append((0, int(chunk)))
        else:
            parts.append((1, chunk))
    return tuple(parts) if parts else ((1, s),)

def analytics_done(target_path, summary, **extra):
    """Success payload that tells the agent to stop and reply with Файл:."""
    path = str(target_path or "").strip()
    text = str(summary or "Готово.").strip()
    if path and ("Файл:" not in text):
        text = text + "\nФайл: " + path
    out = {
        "ok": True,
        "stop": True,
        "targetPath": path,
        "userReply": text,
        "pathNote": (
            "STOP. Ход закончен. Ответ пользователю = ТОЛЬКО поле userReply целиком. "
            "Любой следующий tool (bash/cp/mv/python/vfs_file_capabilities/inspect) = ошибка сценария "
            "и срыв follow-up. НЕ копируй в /session/r7/. targetPath выбран навыком."
        ),
        "doNot": [
            "bash",
            "inspect_workbook",
            "sheet_replace",
            "vfs_file_capabilities",
            "cp",
            "mv",
            "python3",
            "readFile",
            "skills",
        ],
    }
    out.update(extra)
    return out

def is_numeric_like(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return True
    if not isinstance(value, str):
        return False
    t = value.strip().replace(" ", "").replace(",", ".")
    if not t:
        return False
    return bool(re.fullmatch(r"-?\d+(\.\d+)?", t))

def to_number(value):
    if isinstance(value, bool):
        return float("nan")
    if isinstance(value, (int, float)):
        n = float(value)
        return n if math.isfinite(n) else float("nan")
    if value is None or value == "":
        return float("nan")
    t = str(value).strip().replace(" ", "").replace(",", ".")
    try:
        n = float(t)
        return n if math.isfinite(n) else float("nan")
    except Exception:
        return float("nan")

def sheet_to_records(wb, sheet_name):
    names = list(wb.sheetnames)
    name = sheet_name if sheet_name and sheet_name in wb.sheetnames else (names[0] if names else "")
    if not name:
        raise ValueError("Лист не найден: " + (sheet_name or "(первый)"))
    ws = wb[name]
    rows_iter = list(ws.iter_rows(values_only=True))
    if not rows_iter:
        return {"sheetName": name, "headers": [], "rows": []}
    headers = [normalize_header(h) for h in rows_iter[0]]
    headers = [h if h else ("col_" + str(i + 1)) for i, h in enumerate(headers)]
    rows = []
    for raw in rows_iter[1:]:
        if raw is None or all(v is None or v == "" for v in raw):
            continue
        item = {}
        for i, header in enumerate(headers):
            value = raw[i] if i < len(raw) else None
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            item[header] = value
        rows.append(item)
    return {"sheetName": name, "headers": headers, "rows": rows}

def classify_columns(headers, rows, sample_limit=40):
    limit = min(len(rows), sample_limit)
    result = []
    for header in headers:
        numeric = 0
        non_empty = 0
        unique = {}
        for i in range(limit):
            value = rows[i].get(header)
            if value is None or value == "":
                continue
            non_empty += 1
            unique[cell_key(value)] = True
            if is_numeric_like(value):
                numeric += 1
        unique_count = len(unique)
        numeric_ratio = (numeric / non_empty) if non_empty else 0.0
        kind = "categorical"
        if numeric_ratio >= 0.8:
            kind = "numeric"
        elif unique_count > max(20, int(limit * 0.7)):
            kind = "id_or_text"
        result.append({
            "name": header,
            "kind": kind,
            "uniqueSample": unique_count,
            "numericRatio": round(numeric_ratio, 2),
        })
    return result

def suggest_pivot(columns):
    categoricals = [c for c in columns if c["kind"] == "categorical"]
    numerics = [c for c in columns if c["kind"] == "numeric"]
    row_fields = [c["name"] for c in categoricals[: min(2, len(categoricals))]]
    column_fields = []
    for c in categoricals:
        if c["name"] not in row_fields:
            column_fields = [c["name"]]
            break
    if len(row_fields) >= 2 and column_fields:
        row_fields = row_fields[:1]
    preferred = ["Сумма", "Факт", "Бюджет", "Оклад", "Премия", "Количество", "Amount", "Sum", "Total"]
    value_field = ""
    for name in preferred:
        hit = next((c for c in numerics if c["name"] == name), None)
        if hit:
            value_field = hit["name"]
            break
    if not value_field and numerics:
        value_field = numerics[-1]["name"]
    aggregation = "sum" if value_field else "count"
    if not value_field and categoricals:
        value_field = categoricals[0]["name"]
    return {
        "rowFields": row_fields,
        "columnFields": column_fields,
        "valueField": value_field,
        "aggregation": aggregation,
    }

def aggregate(values, mode):
    if not values:
        return None
    if mode == "count":
        return len(values)
    total = sum(values)
    if mode == "sum":
        return total
    if mode == "avg":
        return total / len(values)
    if mode == "min":
        return min(values)
    if mode == "max":
        return max(values)
    return total

def round_smart(value):
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return value
    if float(value).is_integer():
        return int(value)
    return round(float(value), 2)

def build_pivot_aoa(rows, options):
    row_fields = options.get("rowFields") or []
    column_fields = options.get("columnFields") or []
    value_field = options.get("valueField") or ""
    aggregation = str(options.get("aggregation") or "sum").lower()
    column_field = column_fields[0] if column_fields else ""
    if not row_fields:
        raise ValueError("Нужен хотя бы один rowFields")
    if not value_field:
        raise ValueError("valueField обязателен")

    groups = {}
    col_set = {}
    for row in rows:
        row_key_parts = [cell_key(row.get(field)) for field in row_fields]
        row_key = "\u0001".join(row_key_parts)
        col_key = cell_key(row.get(column_field)) if column_field else "__value__"
        if column_field:
            col_set[col_key] = True
        if row_key not in groups:
            groups[row_key] = {"parts": row_key_parts, "cols": {}}
        if col_key not in groups[row_key]["cols"]:
            groups[row_key]["cols"][col_key] = []
        if aggregation == "count":
            groups[row_key]["cols"][col_key].append(1.0)
        else:
            n = to_number(row.get(value_field))
            if math.isfinite(n):
                groups[row_key]["cols"][col_key].append(n)

    col_keys = sorted(col_set.keys(), key=lambda x: x) if column_field else ["__value__"]
    header = list(row_fields)
    if column_field:
        header.extend(col_keys)
        header.append("Итого")
    else:
        header.append(value_field + " (" + aggregation + ")")

    body = []
    col_totals = {k: [] for k in col_keys}
    for row_key in sorted(groups.keys(), key=lambda x: x):
        g = groups[row_key]
        line = list(g["parts"])
        row_values = []
        for key in col_keys:
            agg = aggregate(g["cols"].get(key) or [], aggregation)
            cell = None if agg is None else round_smart(agg)
            line.append(cell)
            if agg is not None:
                row_values.append(agg)
                col_totals[key].append(agg)
        if column_field:
            mode = "sum" if aggregation == "count" else aggregation
            row_total = aggregate(row_values, mode)
            line.append(None if row_total is None else round_smart(row_total))
        body.append(line)

    aoa = [header] + body
    if column_field and body:
        total_line = ["Итого"] + ([""] * (len(row_fields) - 1))
        mode = "sum" if aggregation == "count" else aggregation
        grand = []
        for key in col_keys:
            agg = aggregate(col_totals[key], mode)
            total_line.append(None if agg is None else round_smart(agg))
            if agg is not None:
                grand.append(agg)
        grand_total = aggregate(grand, mode)
        total_line.append(None if grand_total is None else round_smart(grand_total))
        aoa.append(total_line)

    return {
        "aoa": aoa,
        "rowCount": len(body),
        "columnCount": len(header),
        "columnKeys": col_keys if column_field else [],
        "aggregation": aggregation,
        "valueField": value_field,
    }

def stem_from_path(path):
    name = str(path or "").rstrip("/").split("/")[-1]
    lower = name.lower()
    for ext in (".xlsx", ".xlsm", ".xls"):
        if lower.endswith(ext):
            return name[: -len(ext)] or "result"
    return name or "result"

def default_target_path(source_path, suffix):
    stem = stem_from_path(source_path)
    src = str(source_path or "").replace("\\", "/")
    if stem.lower().startswith("r7-") or "/session/r7/" in src.lower():
        stem = suffix
    # ASCII-only filenames — Cyrillic paths break some VFS/plugin downloads.
    safe = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(stem or suffix))[:40].strip("_") or suffix
    suf = re.sub(r"[^a-zA-Z0-9\-]+", "_", str(suffix or "result"))[:24].strip("_") or "result"
    return "/session/" + safe + "_" + suf + ".xlsx"

def normalize_result_path(target_path, source_path, suffix):
    # Ignore model targetPath entirely — agents pass /session/r7/… then try bash cp/mv
    # to "fix" the rewrite. Always choose a stable /session ASCII path.
    _ = target_path
    return default_target_path(source_path, suffix)

def records_to_aoa(headers, rows):
    aoa = [list(headers)]
    for row in rows:
        aoa.append([row.get(h) for h in headers])
    return aoa

async def write_aoa_workbook(vfs, target_path, sheets_aoa, source_path=None):
    """
    sheets_aoa: list of {name, aoa}. Replaces named sheets; creates book if needed.
    If target_path == source_path, starts from source bytes.
    """
    from openpyxl import Workbook, load_workbook
    from openpyxl.utils import get_column_letter

    created_new = False
    if source_path and target_path == source_path:
        buf = await read_workbook_bytes(vfs, source_path)
        wb = load_workbook(io.BytesIO(buf), data_only=False)
    else:
        exists = False
        if callable(getattr(vfs, "exists", None)):
            try:
                exists = bool(await vfs.exists(target_path))
            except Exception:
                exists = False
        if exists:
            buf = await read_workbook_bytes(vfs, target_path)
            wb = load_workbook(io.BytesIO(buf), data_only=False)
        else:
            wb = Workbook()
            created_new = True
            wb.remove(wb.active)

    for item in sheets_aoa:
        name = str(item.get("name") or "Результат")[:31]
        aoa = item.get("aoa") or []
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(title=name)
        for r_idx, row in enumerate(aoa, start=1):
            for c_idx, value in enumerate(row, start=1):
                ws.cell(row=r_idx, column=c_idx, value=value)
        width = max(1, len(aoa[0]) if aoa else 1)
        for col in range(1, width + 1):
            ws.column_dimensions[get_column_letter(col)].width = 16

    out = io.BytesIO()
    wb.save(out)
    payload = out.getvalue()
    write_mode = await write_workbook_bytes(vfs, target_path, payload)
    stored = None
    if callable(getattr(vfs, "getFileMetadata", None)):
        try:
            meta = await vfs.getFileMetadata(target_path)
            if isinstance(meta, dict):
                stored = meta.get("size_bytes") or meta.get("size")
        except Exception:
            stored = None
    return {
        "writeMode": write_mode + ("+created" if created_new else "+updated"),
        "expectedBytes": len(payload),
        "storedBytes": stored,
    }

def parse_cell_date(value):
    from datetime import datetime, date
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None or value == "":
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt).date()
        except Exception:
            continue
    try:
        return datetime.fromisoformat(text.replace("Z", "")).date()
    except Exception:
        return None

def year_month_label(value):
    d = parse_cell_date(value)
    if d is None:
        text = str(value or "").strip()
        if len(text) >= 7 and text[4] == "-":
            return text[:7]
        return ""
    return str(d.year) + "-" + str(d.month).zfill(2)

def match_one_filter(row, rule):
    if not isinstance(rule, dict):
        return True
    field = str(rule.get("field") or "").strip()
    op = str(rule.get("op") or "eq").strip().lower()
    expected = rule.get("value")
    actual = row.get(field)
    if op == "eq":
        return cell_key(actual) == cell_key(expected)
    if op == "ne":
        return cell_key(actual) != cell_key(expected)
    if op == "contains":
        return str(expected or "").lower() in str(actual or "").lower()
    if op == "in":
        values = expected if isinstance(expected, list) else [expected]
        keys = [cell_key(v) for v in values]
        return cell_key(actual) in keys
    if op == "month":
        d = parse_cell_date(actual)
        if d is None:
            return False
        try:
            want = int(str(expected).strip())
        except Exception:
            return False
        return d.month == want
    if op == "year_month":
        return year_month_label(actual) == str(expected or "").strip()[:7]
    if op == "gt":
        return to_number(actual) > to_number(expected)
    if op == "gte":
        return to_number(actual) >= to_number(expected)
    if op == "lt":
        return to_number(actual) < to_number(expected)
    if op == "lte":
        return to_number(actual) <= to_number(expected)
    if op == "empty":
        return actual is None or actual == ""
    if op == "not_empty":
        return actual is not None and actual != ""
    return True

def row_matches_filters(row, filters, match_any=False):
    if not filters:
        return True
    rules = [r for r in filters if isinstance(r, dict)]
    if not rules:
        return True
    if match_any:
        return any(match_one_filter(row, rule) for rule in rules)
    return all(match_one_filter(row, rule) for rule in rules)

def is_excel_name(name):
    lower = str(name or "").lower()
    return lower.endswith(".xlsx") or lower.endswith(".xlsm") or lower.endswith(".xls")

def join_path(base, name):
    if not base or base == "/":
        return "/" + name
    return str(base).rstrip("/") + "/" + name

async def list_excel_in_dir(vfs, dir_path, out, depth):
    if depth > 3:
        return
    if not callable(getattr(vfs, "listDir", None)):
        return
    try:
        entries = await vfs.listDir(dir_path)
    except Exception:
        return
    if isinstance(entries, list):
        lst = entries
    elif isinstance(entries, dict):
        lst = entries.get("entries") or entries.get("items") or []
    else:
        lst = []
    for item in lst:
        name = ""
        full_path = ""
        is_directory = False
        if isinstance(item, str):
            name = item
            full_path = join_path(dir_path, item)
        elif isinstance(item, dict):
            raw_name = str(item.get("name") or item.get("path") or "")
            name = raw_name.split("/")[-1] if raw_name else ""
            full_path = str(item.get("path") or join_path(dir_path, name))
            is_directory = bool(item.get("isDir") or item.get("isDirectory") or item.get("type") in ("dir", "directory"))
        if not name:
            continue
        if is_directory or ("." not in name and not is_excel_name(name)):
            if callable(getattr(vfs, "isDir", None)):
                try:
                    if await vfs.isDir(full_path):
                        await list_excel_in_dir(vfs, full_path, out, depth + 1)
                        continue
                except Exception:
                    pass
            elif is_directory:
                await list_excel_in_dir(vfs, full_path, out, depth + 1)
                continue
        if is_excel_name(name):
            out.append({"path": full_path, "name": name, "root": dir_path})

async def handler(state, params):
    """Prepare open-Cell format op; plugin applies via Asc."""
    params = params if isinstance(params, dict) else {}
    target = get_string(params, "target").strip().lower() or "used"
    if target not in ("used", "selection", "range", "cells"):
        return {"ok": False, "error": "target: used | selection | range | cells"}
    range_addr = get_string(params, "range").strip()
    cells_raw = get_array(params, "cells")
    cells = [str(x or "").strip() for x in cells_raw if str(x or "").strip()]
    if target == "range" and not range_addr:
        return {"ok": False, "error": "range обязателен при target=range"}
    if target == "cells" and not cells:
        return {"ok": False, "error": "cells обязателен при target=cells"}

    fmt_in = params.get("format")
    if not isinstance(fmt_in, dict) or not fmt_in:
        return {"ok": False, "error": "format обязателен (объект со свойствами оформления)"}

    allowed = {
        "bold",
        "italic",
        "fontName",
        "fontSize",
        "fontColorRgb",
        "fillRgb",
        "underline",
        "headerBold",
        "headerFillRgb",
        "bordersOutline",
    }
    unsupported = []
    format_out = {}
    for key, val in fmt_in.items():
        if key not in allowed:
            unsupported.append(str(key))
            continue
        format_out[key] = val

    # Safety: «шапка жирным» на used → headerBold (строка 1), не bold всего листа/столбца.
    if (
        target == "used"
        and format_out.get("bold") is True
        and "headerBold" not in format_out
        and set(format_out.keys()) <= {"bold"}
    ):
        format_out = {"headerBold": True}
    if format_out.get("headerBold") is True and "bold" in format_out:
        del format_out["bold"]

    if not format_out:
        return {
            "ok": False,
            "error": (
                "format пуст после фильтрации. Поддерживаются только: "
                + ", ".join(sorted(allowed))
                + ". Не поддерживаются (в т.ч. толщина/внутренние границы): "
                + (", ".join(unsupported) if unsupported else "—")
            ),
            "supportedFormatKeys": sorted(allowed),
            "rejectedKeys": unsupported,
        }

    data = {
        "target": target,
        "range": range_addr or None,
        "cells": cells if cells else None,
        "format": format_out,
        "rejectedKeys": unsupported if unsupported else None,
    }
    return {
        "ok": True,
        "type": "cell_format",
        "data": data,
        "partial": bool(unsupported),
        "rejectedKeys": unsupported if unsupported else None,
        "note": (
            "Часть полей отброшена (не поддерживаются): " + ", ".join(unsupported)
            if unsupported
            else None
        ),
    }
